content.text:
{
  "name": "SocketCAN总线接口",
  "name_en": "SocketCAN Bus Interface",
  "manufacturer": "",
  "description": "基于 Linux SocketCAN 的 CAN 总线软件通信接口，用于在实验系统中发送 CAN 报文、管理周期发送任务并关闭总线套接字连接。它本身不是物理仪器，而是用于连接和控制 CAN 网络设备的非实体组件。",
  "description_en": "A Linux SocketCAN-based software communication interface for CAN bus messaging, periodic transmission task management, and socket shutdown in laboratory systems. It is not a physical instrument, but a non-physical component used to connect to and control devices on a CAN network.",
  "actions": [
    {
      "action_name": "auto-shutdown",
      "description": "关闭 SocketCAN 总线接口，停止所有活动的周期发送任务并关闭套接字。",
      "description_en": "Shut down the SocketCAN bus interface by stopping all active periodic send tasks and closing the socket."
    },
    {
      "action_name": "auto-send",
      "description": "向 CAN 总线发送一条报文，并可在设定超时时间内等待发送队列可用。",
      "description_en": "Send a message onto the CAN bus, optionally waiting up to a timeout for the transmit queue to become available."
    },
    {
      "action_name": "auto-fileno",
      "description": "获取该 SocketCAN 接口底层套接字的文件描述符。",
      "description_en": "Get the file descriptor of the underlying socket used by this SocketCAN interface."
    }
  ],
  "tag_hints": [
    "SocketCAN",
    "CAN bus communication",
    "Linux socket interface",
    "periodic message transmission",
    "bus messaging",
    "instrument network integration"
  ]
}

